import { StyleFn } from "..";
import { focus } from "../../helpers";

export const AnchorNav: StyleFn = (theme, mode) => {
  const { font, opacity, size, color } = theme;
  const textColor = color.text.link.neutral.default[mode];
  const { focusWithPseudo } = focus(theme, mode);

  return {
    root: {
      height: "100%",
      overflowY: "auto",
      maxWidth: size.spacing[128],
      display: "flex",
      flexDirection: "column",
      color: textColor,
    },
    title: {
      color: textColor,
      fontSize: font.size.small,
      fontWeight: font.weight.medium,
    },
    list: {
      color: textColor,
      fontSize: font.size.medium,
      fontWeight: font.weight.regular,
      listStyle: "none",
      paddingLeft: 0,
    },
    item: {
      display: "flex",
      position: "relative",
      fontWeight: font.weight.bold,
      lineHeight: size.spacing[24],
      borderLeft: `2px solid ${color.surface.componentbackground.moderate[mode]}`,
      "&:first-child": {
        "& $itemLink": { marginTop: "unset" },
        "&:before": { top: 0 },
      },
      "&:last-child": {
        "& $itemLink": { marginBottom: "unset" },
        "&:before": { bottom: 0 },
      },
      "&:before": {
        position: "absolute",
        content: "''",
        width: size.spacing[2],
        top: size.spacing[8],
        bottom: size.spacing[8],
        left: "-" + size.spacing[2],
        backgroundColor: "transparent",
      },
    },
    item_secondary: {
      fontSize: font.size.small,
      fontWeight: font.weight.regular,
      paddingLeft: size.spacing[8],
      lineHeight: size.spacing[20],
      "& $itemLink": {
        margin: `${size.spacing[6]} ${size.spacing[8]}`,
      },
    },
    item_selected: {
      fontWeight: font.weight.bold,
      "& $itemLink": {
        color: color.text.link.neutral.active[mode],
      },
      "&$item:before": {
        left: -2,
        backgroundColor: color.surface.accent.active[mode],
        borderRadius: 1,
      },
    },
    item_disabled: {
      cursor: "not-allowed",
      "& $itemLink": {
        opacity: opacity.disabled,
        cursor: "not-allowed",
        pointerEvents: "none",
      },
    },
    itemLink: {
      ...focusWithPseudo({
        radius: "5px",
        transparentBorder: false,
      }),
      textDecoration: "none",
      margin: `${size.spacing[8]} ${size.spacing[8]}`,
      color: color.text.link.neutral.default[mode],
      "&:hover:not([disabled])": {
        color: color.text.link.neutral.hover[mode],
      },
      "&:active:not([disabled])": {
        color: color.text.link.neutral.active[mode],
      },
    },
  };
};
